R=Path(__file__).resolve().parents[1];D=R/'dist';T=R/'wordpress/oakline';SITE='https://mhashim-eng.github.io/hashim-portfolio/oakline'
def b(name,content='',attrs=None):
 return '<!-- wp:'+name+((' '+json.dumps(attrs,separators=(',',':'))) if attrs else '')+' -->'+content+'<!-- /wp:'+name+' -->'
def p(text,cls=''):return b('paragraph',f'<p'+(f' class="{cls}"' if cls else '')+f'>{text}</p>',{'className':cls} if cls else None)
def h(text,n=2,cls=''):return b('heading',f'<h{n} class="wp-block-heading'+(' '+cls if cls else '')+f'">{text}</h{n}>',{'level':n,**({'className':cls} if cls else {})})
def g(content,cls,tag='div',id=''):return b('group',f'<{tag}'+(f' id="{id}"' if id else '')+f' class="wp-block-group {cls}">{content}</{tag}>',{'tagName':tag,'className':cls,**({'anchor':id} if id else {})})
def img(name,alt,cls='',link=False,eager=False):
 i=f'<img src="{{{{ASSET}}}}/{name}.webp" alt="{alt}"/>'
 if link:i=f'<a href="{{{{ASSET}}}}/{name}.webp">{i}</a>'
 return b('image',f'<figure class="wp-block-image size-full {cls}">{i}</figure>',{'sizeSlug':'full','linkDestination':'media' if link else 'none','className':cls})
def btn(text,url='{{CONTACT}}',outline=False):return b('buttons',b('button',f'<div class="wp-block-button'+(' is-style-outline' if outline else '')+f'"><a class="wp-block-button__link wp-element-button" href="{url}">{text} <span aria-hidden="true">↗</span></a></div>',{'className':'is-style-outline'} if outline else None))
def eyebrow(s):return p(s,'eyebrow')
def section(content,cls='',id=''):return g(g(content,'wrap'),'section '+cls,'section',id)
def intro(k,title,desc):return section(eyebrow(k)+h(title,1)+p(desc,'lead'),'page-intro')
services=[('kitchen','Kitchen Remodeling','kitchen','The heart of home, reimagined.','Cabinet updates, thoughtful layouts, new countertops and layered lighting—made for the way you cook, gather and live.',['Storage that works harder','A layout that feels natural','Finishes with lasting appeal']),('bathroom','Bathroom Renovation','bathroom','A little calm in your everyday.','Modern showers, considered tilework, beautiful vanities and updated fixtures turn everyday routines into something special.',['Practical, easy-care surfaces','Considered lighting and fixtures','A cohesive, relaxing space']),('flooring','Flooring Installation','living','A beautiful foundation.','Explore hardwood, luxury vinyl and tile, with room-by-room material choices and a coordinated installation plan.',['Materials suited to your lifestyle','A consistent look across rooms','Thoughtful transitions and details']),('whole-home','Whole-Home Renovation','detail','Bring the whole vision together.','Coordinated improvements across multiple rooms, with a clear scope, connected design decisions and a practical project sequence.',['One cohesive design direction','Coordinated project planning','Spaces that work better together'])]
